import React, { useEffect, useState } from 'react';
import api from '../api';

export default function AdminDashboard(){
  const [books, setBooks] = useState([]);
  const [form, setForm] = useState({ title:'', author:'', price:0, stock:0, category:'', language:'', description:'', coverFile: null });

  async function load(){
    try {
      const res = await api.get('/api/books');
      setBooks(res.data.data);
    } catch(err){ alert(err?.response?.data?.message || err.message); }
  }

  useEffect(()=>{ load(); }, []);

  async function create(e){
    e.preventDefault();
    try {
      const fd = new FormData();
      Object.keys(form).forEach(k => { if(k!=='coverFile') fd.append(k, form[k]); else if(form.coverFile) fd.append('cover', form.coverFile); });
      const res = await api.post('/api/books', fd, { headers: { 'Content-Type': 'multipart/form-data' }});
      setForm({ title:'', author:'', price:0, stock:0, category:'', language:'', description:'', coverFile: null });
      load();
    } catch(err){ alert(err?.response?.data?.message || err.message); }
  }

  async function remove(id){
    if(!window.confirm('Delete book?')) return;
    try { await api.delete(`/api/books/${id}`); load(); } catch(err){ alert(err?.response?.data?.message || err.message); }
  }

  return (
    <div>
      <h2 className="text-2xl font-bold mb-4">Admin Dashboard</h2>
      <div className="grid md:grid-cols-3 gap-6">
        <div className="md:col-span-1 bg-white p-4 rounded shadow">
          <h3 className="font-semibold mb-2">Add Book</h3>
          <form onSubmit={create} className="space-y-2">
            <input value={form.title} onChange={e=>setForm({...form,title:e.target.value})} placeholder="Title" className="w-full p-2 border rounded" />
            <input value={form.author} onChange={e=>setForm({...form,author:e.target.value})} placeholder="Author" className="w-full p-2 border rounded" />
            <input type="number" value={form.price} onChange={e=>setForm({...form,price:Number(e.target.value)})} placeholder="Price" className="w-full p-2 border rounded" />
            <input type="number" value={form.stock} onChange={e=>setForm({...form,stock:Number(e.target.value)})} placeholder="Stock" className="w-full p-2 border rounded" />
            <input value={form.category} onChange={e=>setForm({...form,category:e.target.value})} placeholder="Category" className="w-full p-2 border rounded" />
            <input value={form.language} onChange={e=>setForm({...form,language:e.target.value})} placeholder="Language" className="w-full p-2 border rounded" />
            <input type="file" onChange={e=>setForm({...form, coverFile: e.target.files[0]})} className="w-full" />
            <textarea value={form.description} onChange={e=>setForm({...form,description:e.target.value})} placeholder="Description" className="w-full p-2 border rounded" />
            <button className="w-full bg-blue-600 text-white py-2 rounded">Create</button>
          </form>
        </div>
        <div className="md:col-span-2">
          <h3 className="font-semibold mb-4">Books</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            {books.map(b => (
              <div key={b._id} className="bg-white p-3 rounded shadow flex justify-between items-center">
                <div>
                  <div className="font-semibold">{b.title}</div>
                  <div className="text-sm text-gray-600">{b.author}</div>
                </div>
                <div className="flex items-center gap-2">
                  <button onClick={()=>remove(b._id)} className="text-red-600">Delete</button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}
